class Solution:
    def longestCommonPrefix(self, strs):
        prefix = strs[0]
        for s in strs[1:]:
            limit = min(len(prefix), len(s))
            i = 0
            while i < limit and prefix[i] == s[i]:
                i += 1
            prefix = prefix[:i]
            if not prefix:
                break
        return prefix

