#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* longestCommonPrefix(char** strs, int strsSize) {
    size_t prefixLen = strlen(strs[0]);
    for (int k = 1; k < strsSize; ++k) {
        size_t sLen = strlen(strs[k]);
        size_t limit = prefixLen < sLen ? prefixLen : sLen;
        size_t i = 0;
        while (i < limit && strs[0][i] == strs[k][i]) ++i;
        prefixLen = i;
        if (prefixLen == 0) break;
    }
    char* out = (char*)malloc(prefixLen + 1);
    if (!out) return NULL;
    memcpy(out, strs[0], prefixLen);
    out[prefixLen] = '\0';
    return out;
}

